  ('2b8f0cee-320d-45ba-9c5a-1cf3971ef2b4', $$Biologie$$, $$VWO$$, $$De eerste ademteug$$, $$VWO Biologie 2019-I$$),
  ('3223f568-d4d6-480d-8064-8da560d7340b', $$Biologie$$, $$VWO$$, $$Mambagif als pijnstiller$$, $$VWO Biologie 2019-I$$),
  ('3cfba86d-1f51-4412-9c82-9a0808c20163', $$Biologie$$, $$VWO$$, $$Aziatische genen verbeteren het Europees vleesvarken$$, $$VWO Biologie 2019-I$$),
  ('8ccd3ea4-8d6d-4fd6-8759-25a0232f323d', $$Biologie$$, $$VWO$$, $$Diarreebacterie slaat toe door antibioticagebruik$$, $$VWO Biologie 2019-I$$),
  ('bc27ae2d-7e42-40e0-a099-82c6fdba2563', $$Biologie$$, $$VWO$$, $$Kas vol koolstofdioxide$$, $$VWO Biologie 2019-I$$);

insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('5d37b09f-23b6-47f1-bced-61c9147e6949', '2b8f0cee-320d-45ba-9c5a-1cf3971ef2b4', $$inleiding: de eerste ademteug is een spannend moment (afbeelding 1)$$,
   $$biologie-vwo-2019-i-de-eerste-ademteug-context1.png$$,
   $$De eerste ademteug na de geboorte is een spannend moment. Vooral bij een te vroeg geboren baby gaat ademhalen moeilijk en vaak moet dan worden beademd (afbeelding 1). Nieuwe behandelingen vergroten de overlevingskans van een te vroeg geboren baby.
afbeelding 1: foto van een te vroeg geboren baby die met een maskertje wordt beademd.$$, 'inline'),
  ('051a8190-37f5-47cd-ac81-8c7d1df8cc1f', '2b8f0cee-320d-45ba-9c5a-1cf3971ef2b4', $$gaswisseling verandert bij de geboorte van placentair naar longademhaling$$,
   $$biologie-vwo-2019-i-de-eerste-ademteug-context2.png$$,
   $$Na de geboorte vindt er bij een baby een grote verandering in de manier van gaswisseling plaats. Vóór de geboorte werden zuurstof en koolstofdioxide via de placenta uitgewisseld. Meteen na de geboorte worden de longblaasjes voor het eerst volgezogen met lucht en gaat er meer bloed naar de longen.$$, 'inline'),
  ('09f2ddfe-2159-4b64-be37-ec37c9646f26', '2b8f0cee-320d-45ba-9c5a-1cf3971ef2b4', $$de ademprikkel neemt na de geboorte steeds meer toe$$,
   $$biologie-vwo-2019-i-de-eerste-ademteug-context3.png$$,
   $$Het duurt vaak even voordat een pasgeboren baby ademt. In die korte tijd neemt de ademprikkel steeds meer toe, waarna de ademhaling op gang komt.$$, 'inline'),
  ('4d889ffb-ae3a-440e-8035-d7b452fbd9ba', '2b8f0cee-320d-45ba-9c5a-1cf3971ef2b4', $$ademhalingsspieren betrokken bij de longventilatie (afbeelding 2)$$,
   $$biologie-vwo-2019-i-de-eerste-ademteug-context4.png$$,
   $$Enkele spieren die betrokken zijn bij de longventilatie zijn in afbeelding 2 met een nummer aangeduid. Met pijlen is aangegeven in welke richting de ribben bewegen als deze spiergroepen samentrekken. Ook de richting waarin het middenrif beweegt als de middenrifspieren samentrekken, is met een pijl aangegeven.
afbeelding 2: tekening van de borstkas met vijf genummerde ademhalingsspieren (1 halsspieren, 2 buitenste tussenribspieren, 3 binnenste tussenribspieren, 4 middenrifspieren, 5 buikspieren) en pijlen die de bewegingsrichting bij samentrekking aangeven.$$, 'inline'),
  ('ee7b88af-b28d-47d5-9a6a-7826325ee952', '2b8f0cee-320d-45ba-9c5a-1cf3971ef2b4', $$ontwikkelingsfasen van de bronchioli (afbeelding 3)$$,
   $$biologie-vwo-2019-i-de-eerste-ademteug-context5.png$$,
   $$Hoe goed de gaswisseling verloopt na de geboorte is afhankelijk van het ontwikkelingsstadium van de longen. In afbeelding 3 zijn de anatomische veranderingen van bronchioli (waaruit zich de longblaasjes ontwikkelen) in verschillende ontwikkelingsfasen weergegeven.
afbeelding 3: drie tekeningen van een bronchiole met haarvaten en epitheelcellen, in de canaliculaire fase (vanaf de 16e week), de sacculaire fase (vanaf de 24e week) en de alveolaire fase (vanaf de 32e week).
Vanaf de 26e week van de embryonale ontwikkeling wordt in de bronchioli een steeds grotere hoeveelheid surfactant geproduceerd. Surfactant is een mengsel van lipiden en eiwitten dat ervoor dient om de oppervlaktespanning in de longblaasjes te verlagen. Daardoor kunnen de longblaasjes makkelijker open blijven.$$, 'inline'),
  ('863e41fb-112c-4916-bbe2-9ed5941de8c9', '2b8f0cee-320d-45ba-9c5a-1cf3971ef2b4', $$overlevingskans is groter in de sacculaire fase dan in de canaliculaire fase$$,
   $$biologie-vwo-2019-i-de-eerste-ademteug-context6.png$$,
   $$Bij een vroeggeboorte zijn de overlevingskansen voor een baby waarvan de longen in de sacculaire fase verkeren groter dan wanneer de longen nog in de canaliculaire fase zijn. Een verklaring hiervoor is de verbeterde gaswisseling door veranderingen in de bouw van het longweefsel.$$, 'inline'),
  ('8a335dde-78e0-406d-944a-5d2a182ff942', '2b8f0cee-320d-45ba-9c5a-1cf3971ef2b4', $$klassieke mechanische beademing kan longblaasjes beschadigen$$,
   $$biologie-vwo-2019-i-de-eerste-ademteug-context7.png$$,
   $$Een te vroeg geboren baby met ernstige ademhalingsproblemen wordt behandeld met behulp van een mechanisch beademingsapparaat. De klassieke manier van beademen is dat de longen worden volgepompt en weer leeggezogen. Bij het leegzuigen kunnen longblaasjes dichtklappen. Ook bij het volpompen kan er schade ontstaan aan de tere longblaasjes.$$, 'inline'),
  ('c67f13ec-2e26-4d03-9716-1bd79c86c4c2', '2b8f0cee-320d-45ba-9c5a-1cf3971ef2b4', $$klaplong door beschadiging van het longvlies; longwaarden (afbeelding 4)$$,
   $$biologie-vwo-2019-i-de-eerste-ademteug-context8.png$$,
   $$Mogelijke gevolgen van de klassieke mechanische beademing zijn dat longblaasjes knappen en het longvlies wordt geperforeerd. Hierdoor laat het longvlies los van het borstvlies. Er is dan een klaplong ontstaan (afbeelding 4).
afbeelding 4: tekening van een baby met een klaplong, met een legenda van borstvlies (1), longvlies (2) en interpleurale ruimte (3).
Enkele longwaarden zijn:
1 restvolume
2 totale longvolume
3 vitale capaciteit$$, 'inline'),
  ('cfbaf2d5-c504-41c3-af61-8045ea8f1f17', '2b8f0cee-320d-45ba-9c5a-1cf3971ef2b4', $$CPAP-beademing vermindert schade vooral tijdens de uitademing$$,
   $$biologie-vwo-2019-i-de-eerste-ademteug-context9.png$$,
   $$Om beschadiging van de nog niet goed ontwikkelde longen te voorkomen, wordt bij voorkeur CPAP (continuous positive airway pressure, afbeelding 1) toegepast: via een maskertje wordt continu lucht met een licht verhoogde luchtdruk naar de longen gevoerd. CPAP-beademing vergemakkelijkt het vullen van de longblaasjes. Het belangrijkste effect heeft het inblazen van de lucht echter tijdens de uitademing: er is minder risico op beschadiging aan de longblaasjes van vroeggeborenen dan bij klassieke beademing.$$, 'inline'),
  ('7c3425f2-5b71-4609-9cbd-4c7729cddc72', '2b8f0cee-320d-45ba-9c5a-1cf3971ef2b4', $$vroeggeborene heeft minder monocyten dan een voldragen baby$$,
   $$biologie-vwo-2019-i-de-eerste-ademteug-context10.png$$,
   $$Bij alle behandelingen moet zo steriel mogelijk gewerkt worden, omdat ook het immuunsysteem van een vroeggeboren baby nog niet goed ontwikkeld is. De vroeggeborene bezit minder monocyten (voorlopers van macrofagen) dan een voldragen baby.$$, 'inline'),
  ('420a75cf-6369-42c0-86e0-8481a8b90de3', '3223f568-d4d6-480d-8064-8da560d7340b', $$inleiding: de zwarte mamba is de giftigste slang van Afrika (afbeelding 1)$$,
   $$biologie-vwo-2019-i-mambagif-als-pijnstiller-context1.png$$,
   $$De zwarte mamba (Dendroaspis polylepis, afbeelding 1) is de giftigste slang van Afrika. Met een snelle beet injecteert zij een gifcocktail die een mens binnen 20 minuten kan doden.
afbeelding 1: foto van een zwarte mamba.$$, 'inline'),
  ('6a668ef7-c6fc-4eeb-901b-535e19887675', '3223f568-d4d6-480d-8064-8da560d7340b', $$antiserum tegen mambagif kan een allergische reactie veroorzaken$$,
   $$biologie-vwo-2019-i-mambagif-als-pijnstiller-context2.png$$,
   $$Als je wordt gebeten door de zwarte mamba, moet je zo snel mogelijk een antiserum toegediend krijgen. Antiserum wordt verkregen uit dieren, vaak paarden, die geïmmuniseerd zijn door een injectie met het slangengif. Nadat je antiserum toegediend hebt gekregen, kan echter een allergische reactie ontstaan.$$, 'inline'),
  ('aafd7785-ed56-46f3-89a2-fc0783ee0659', '3223f568-d4d6-480d-8064-8da560d7340b', $$drie processen van het afweersysteem$$,
   $$biologie-vwo-2019-i-mambagif-als-pijnstiller-context3.png$$,
   $$Een aantal processen van het afweersysteem zijn:
1 activatie van cytotoxische T-cellen
2 sensibilisatie van mestcellen
3 afgifte van mediatoren$$, 'inline'),
  ('88e55c5d-2578-4938-85ba-a8c29ac8cb4d', '3223f568-d4d6-480d-8064-8da560d7340b', $$pijnreceptoren: Aδ-receptoren geven scherpe pijn, C-receptoren geven zeurende pijn$$,
   $$biologie-vwo-2019-i-mambagif-als-pijnstiller-context4.png$$,
   $$Onderzoekers van het Moleculair en Cellulair Farmacologisch Instituut in Valbonne (Frankrijk) vonden twee krachtige pijnstillende eiwitten in het gif van de mamba. Pijn heeft een functie bij het beperken of vermijden van lichaamsschade en wordt veroorzaakt door stimulering van uiteinden van speciale sensorische neuronen. Deze pijnreceptoren kunnen reageren op thermische prikkels (hitte, kou), mechanische prikkels (aanraking, druk) en chemische prikkels. Wanneer pijnreceptoren worden gestimuleerd beschrijven mensen de pijn óf als een snelle, kortdurende scherpe pijn óf als een langdurige zeurende pijn. Scherpe pijn wordt ervaren bij stimulatie van Aδ-receptoren. Dit type pijn is niet voelbaar in de meeste diepliggende weefsels en organen. De zeurende pijn wordt ervaren bij stimulering van C-receptoren, bijvoorbeeld als gevolg van een ontsteking. Deze pijnreceptoren komen zowel in de huid als in de dieper liggende organen voor.$$, 'inline'),
  ('7c0f4e01-1558-4601-ab3a-7ed88bee0516', '3223f568-d4d6-480d-8064-8da560d7340b', $$ASIC-kanalen worden geopend door protonen (afbeelding 2)$$,
   $$biologie-vwo-2019-i-mambagif-als-pijnstiller-context5.png$$,
   $$ASIC-kanalen (acid sensing ion channels, afbeelding 2) in het membraan van bepaalde neuronen zijn betrokken bij het genereren van pijnsignalen. Beschadigde cellen scheiden protonen (H⁺) uit. Deze protonen kunnen pijn opwekken doordat ze ASIC-kanalen van pijnreceptoren openen.
afbeelding 2: schema van een ASIC-kanaal in het celmembraan van een pijnreceptor, met instroom van Na⁺ en H⁺ vanuit de extracellulaire ruimte naar het intracellulaire deel van de cel.$$, 'inline'),
  ('f7d57125-d5ef-4a5c-9607-ad33c4ad19fc', '3223f568-d4d6-480d-8064-8da560d7340b', $$pijn door een slangenbeet wordt via sensorische neuronen naar de hersenen geleid$$,
   $$biologie-vwo-2019-i-mambagif-als-pijnstiller-context6.png$$,
   $$Als je door een slang in je hand gebeten wordt, doet dat pijn doordat in de pijnreceptoren impulsen ontstaan die via sensorische neuronen en schakelcellen naar de hersenen worden geleid.$$, 'inline'),
  ('9789bda9-7b56-47b5-b02c-a793f3251c7c', '3223f568-d4d6-480d-8064-8da560d7340b', $$dwarsdoorsnede van hersenen en ruggenmerg met acht genummerde neuronen (afbeelding 3)$$,
   $$biologie-vwo-2019-i-mambagif-als-pijnstiller-context7.png$$,
   $$Een dwarsdoorsnede door de grote hersenen en een dwarsdoorsnede door het ruggenmerg zijn schematisch weergegeven in afbeelding 3. Een aantal neuronen is aangegeven met de nummers 1 tot en met 8.
afbeelding 3: schematische dwarsdoorsnede van de grote hersenen (met neuronen 1, 2, 3 en 4) en van het ruggenmerg (met neuronen 5, 6, 7 en 8), met synapsen tussen de neuronen.$$, 'inline'),
  ('10c17b0c-b7cb-43b0-9963-f3e3672c7256', '3223f568-d4d6-480d-8064-8da560d7340b', $$een slangenbeet in de rechterhand leidt tot impulsen naar de hersenen$$,
   $$biologie-vwo-2019-i-mambagif-als-pijnstiller-context8.png$$,
   $$Na een slangenbeet in de rechterhand worden impulsen naar de hersenen geleid.$$, 'inline'),
  ('54bd9540-77f6-420b-8e9e-1471595d9d04', '3223f568-d4d6-480d-8064-8da560d7340b', $$onderzoek naar pijnbeleving gebeurt eerst dierexperimenteel$$,
   $$biologie-vwo-2019-i-mambagif-als-pijnstiller-context9.png$$,
   $$Welk type pijn ervaren wordt, kan het best worden onderzocht bij mensen, maar dat stuit op bezwaren. Daarom vindt in eerste instantie dierexperimenteel onderzoek plaats, met een beperkt bruikbaar resultaat.$$, 'inline'),
  ('14698767-1167-4e41-81fe-fac9eb318a6b', '3223f568-d4d6-480d-8064-8da560d7340b', $$muizenexperiment met morfine en mambalgine (afbeelding 4)$$,
   $$biologie-vwo-2019-i-mambagif-als-pijnstiller-context10.png$$,
   $$Om hevige pijn te onderdrukken wordt in het ziekenhuis soms morfine toegediend, maar morfine heeft een aantal vervelende bijwerkingen. In slangengif van de zwarte mamba vond de Franse onderzoeksgroep een alternatief voor morfine. Het slangengifeiwit mambalgine blijkt pijn bij muizen te onderdrukken, zonder zichtbare bijwerkingen. De onderzoekers bestudeerden de werking van dit mambalgine in een experiment met muizen. De muizen werden in drie groepen verdeeld die alle een injectie in de hersenvloeistof kregen:
− Groep 1 kreeg een oplossing met 31 nanomol morfine.
− Groep 2 kreeg een oplossing met 0,34 nanomol mambalgine.
− Groep 3 kreeg een controlevloeistof ingespoten.
Na de injectie werd op verschillende tijdstippen aan de staart van de muizen een pijnprikkel toegediend. Vervolgens werd genoteerd hoe snel de muizen daarop reageerden door hun staart terug te trekken. De resultaten van deze proef zijn weergegeven in afbeelding 4.
afbeelding 4: grafiek van de reactietijd (seconden) tegen de tijd na injectie (minuten, van -15 tot 75) voor morfine, mambalgine en controlevloeistof, met twee controlemetingen vóór de injectie.$$, 'inline'),
  ('6987b231-a383-47ac-9ebc-4725b18a793a', '3223f568-d4d6-480d-8064-8da560d7340b', $$drie beweringen over de twee extra metingen vóór de injectie$$,
   $$biologie-vwo-2019-i-mambagif-als-pijnstiller-context11.png$$,
   $$Bij de muizen is op twee tijdstippen vóór het toedienen van een injectie de terugtrekreactie van de staart genoteerd. Over deze twee extra metingen worden drie beweringen gedaan:
1 Daarmee kun je controleren of het injecteren zelf een verandering in de terugtrekreactie geeft.
2 Daarmee kun je controleren of de toegediende prikkel een meetbaar effect heeft.
3 Daarmee kun je bepalen wat de (gemiddelde) ‘basissnelheid’ is van de terugtrekreacties.$$, 'inline'),
  ('d56f428e-0e0d-47d7-a72e-e6df7ad215f0', '3223f568-d4d6-480d-8064-8da560d7340b', $$twee beweringen over het effect van morfine versus mambalgine$$,
   $$biologie-vwo-2019-i-mambagif-als-pijnstiller-context12.png$$,
   $$Twee beweringen naar aanleiding van het muizenexperiment zijn:
1 Morfine heeft een sterker pijnstillend effect dan eenzelfde dosering mambalgine.
2 De pijnstilling door morfine is van kortere duur dan de pijnstilling door mambalgine.$$, 'inline'),
  ('cead0d45-a9c6-4e1a-932a-03a1e1296954', '3223f568-d4d6-480d-8064-8da560d7340b', $$mambalgine grootschalig produceren vereist een genconstruct met cDNA$$,
   $$biologie-vwo-2019-i-mambagif-als-pijnstiller-context13.png$$,
   $$Als mambalgine een nieuw medicijn bij pijnbestrijding wordt, is het nodig om het grootschalig te produceren. Dit kan door het mambalgine-gen in te brengen in het genoom van een bacterie. Vervolgens zou deze bacterie onder gecontroleerde omstandigheden mambalgine kunnen produceren. Het DNA dat daartoe moet worden ingebouwd is een genconstruct dat onder andere cDNA (copy-DNA) van het mambalgine-gen omvat.$$, 'inline'),
  ('5b9c9294-006c-41e0-ba56-4022bb553e53', '3223f568-d4d6-480d-8064-8da560d7340b', $$cDNA wordt gemaakt vanuit mambalgine-mRNA met reverse transcriptase$$,
   $$biologie-vwo-2019-i-mambagif-als-pijnstiller-context14.png$$,
   $$Het cDNA wordt verkregen door van mambalgine-mRNA, met behulp van het enzym reverse transcriptase, mambalgine-cDNA te maken.$$, 'inline'),
  ('24e2dab5-a27a-4482-9ea9-1e7f68d2a610', '3223f568-d4d6-480d-8064-8da560d7340b', $$voor recombinant-DNA zijn levende cellen uit de gifklier nodig$$,
   $$biologie-vwo-2019-i-mambagif-als-pijnstiller-context15.png$$,
   $$Voor het maken van het recombinant-DNA zijn levende cellen uit de gifklier van een slang nodig.$$, 'inline'),
  ('819574c0-db90-4d24-b7f0-cabea66d0cdf', '3cfba86d-1f51-4412-9c82-9a0808c20163', $$inleiding: Chinese zeugen verbeterden het Europees vleesvarken$$,
   $$biologie-vwo-2019-i-aziatische-genen-verbeteren-het-europees-vleesvarken-context1.png$$,
   $$Veel gunstige eigenschappen van het Europees vleesvarken zijn afkomstig van Chinese zeugen. Deze eigenschappen werden ingekruist om het Europese varkensras te verbeteren.$$, 'inline'),
  ('7950fae6-6be0-44c2-8d12-ff3891038370', '3cfba86d-1f51-4412-9c82-9a0808c20163', $$ontstaan van het Europees vleesvarken uit het wild zwijn (afbeelding 1)$$,
   $$biologie-vwo-2019-i-aziatische-genen-verbeteren-het-europees-vleesvarken-context2.png$$,
   $$Na het ontstaan van het wild zwijn (Sus scrofa), ongeveer 4 miljoen jaar geleden, heeft deze voorouder van onze vleesvarkens zich vanuit Zuidoost-Azië over Eurazië verspreid. Domesticatie van varkens heeft zo’n 10.000 jaar geleden zowel in Europa als in Azië plaatsgevonden. Het huidige Europees vleesvarken (Sus scrofa domesticus) is ongeveer 200 jaar geleden ontstaan in het Verenigd Koninkrijk. De Engelse varkenshouders haalden destijds zeugen uit China die vruchtbaarder en vetter waren en kruisten die met hun eigen varkens. Dankzij de Aziatische genen produceren onze vleesvarkens nu meer biggetjes en beter vlees. In afbeelding 1 is dit in een vereenvoudigd cladogram weergegeven.
afbeelding 1: kaart van Europa en Azië met een cladogram dat toont hoe het wild zwijn (Sus scrofa) zich splitste in het Europees vleesvarken en het Aziatisch tam varken, met een pijl die de inkruising van Aziatische genen in het Europese ras aangeeft.$$, 'inline'),
  ('a9ea2051-573d-48c0-ac96-3f87cdbb1f74', '3cfba86d-1f51-4412-9c82-9a0808c20163', $$Aziatische en Europese varkensrassen leefden lange tijd geografisch gescheiden$$,
   $$biologie-vwo-2019-i-aziatische-genen-verbeteren-het-europees-vleesvarken-context3.png$$,
   $$De gedomesticeerde Aziatische en Europese varkensrassen leefden geografisch gescheiden van elkaar tot de mens ze bij elkaar bracht.$$, 'inline'),
  ('8b9048f6-e010-4419-aaf7-0cd62f64eeba', '3cfba86d-1f51-4412-9c82-9a0808c20163', $$gedomesticeerde rassen hebben meestal minder genetische variatie dan wilde populaties$$,
   $$biologie-vwo-2019-i-aziatische-genen-verbeteren-het-europees-vleesvarken-context4.png$$,
   $$Gedomesticeerde dierenrassen hebben meestal een geringere genetische variatie dan populaties in het wild. Uit onderzoek blijkt dat de genetische variatie bij het Europees vleesvarken juist groot is.$$, 'inline'),
  ('eba761ea-720f-4f8a-8cfd-c4a1d227c7c7', '3cfba86d-1f51-4412-9c82-9a0808c20163', $$energiestroomschema voor vleesvarkens (afbeelding 2)$$,
   $$biologie-vwo-2019-i-aziatische-genen-verbeteren-het-europees-vleesvarken-context5.png$$,
   $$In afbeelding 2 is een energiestroomschema weergegeven dat voor vleesvarkens gebruikt kan worden. Hierin zijn vijf componenten met een letter aangegeven.
afbeelding 2: energiestroomschema met de componenten I (inname energie), A (assimilatie/resorptie), P (productiviteit), R (respiratie/dissimilatie) en F (feces/ontlasting).$$, 'inline'),
  ('6e557905-d515-4804-8d8c-770da541eafd', '3cfba86d-1f51-4412-9c82-9a0808c20163', $$de voedsel-naar-vlees-conversiefactor is verbeterd doordat component R kleiner werd$$,
   $$biologie-vwo-2019-i-aziatische-genen-verbeteren-het-europees-vleesvarken-context6.png$$,
   $$De voedsel-naar-vlees-conversiefactor geeft aan welk deel van de energie in het varkensvoer wordt omgezet in varkensvlees. Door gericht fokken heeft het huidige vleesvarken een heel gunstige conversiefactor gekregen, onder andere doordat component R kleiner is geworden.$$, 'inline'),
  ('7571b3f9-7845-4195-8238-9cdc73758095', '3cfba86d-1f51-4412-9c82-9a0808c20163', $$gekoppelde overerving kan het combineren van eigenschappen bemoeilijken$$,
   $$biologie-vwo-2019-i-aziatische-genen-verbeteren-het-europees-vleesvarken-context7.png$$,
   $$Als een varkenshouder streeft naar een bepaalde combinatie van eigenschappen kan dit bemoeilijkt worden door gekoppelde overerving. Tijdens de meiose kan de koppeling van genen verbroken worden.$$, 'inline'),
  ('37762223-9490-4a89-a57a-5f98fafa18d1', '3cfba86d-1f51-4412-9c82-9a0808c20163', $$kruisings- en terugkruisingsprogramma Duroc x Jinhua (afbeelding 3)$$,
   $$biologie-vwo-2019-i-aziatische-genen-verbeteren-het-europees-vleesvarken-context9.png$$,
   $$In Japan is de vleeskwaliteit van het hoogproductieve varkensras Duroc verbeterd door genen van het Jinhua-varken in te kruisen. Jinhua-varkens hebben mals vlees, maar zijn weinig productief. In afbeelding 3 is weergegeven hoe door kruising en terugkruising op de klassieke manier het varkensras veredeld kan worden.
afbeelding 3: schema van het kruisingsprogramma in vijf stappen (stap 1 t/m 5) tussen Duroc-beren en Jinhua-zeugen/hybride nakomelingen, met de generaties F1 tot en met F5.
− Stap 1: kruising tussen een Duroc-beer (mannetje) en Jinhua-zeugen (vrouwtjes) om een ‘hybride’ F1-generatie te produceren.
− Stap 2: van deze F1 worden de zeugen gebruikt om terug te kruisen met een andere Duroc-beer. Uit deze kruising ontstaat een F2.
− Stap 3 en 4: het terugkruisen met een Duroc-beer wordt nog twee keer herhaald en levert een groep F4-beren en F4-zeugen op.
− Stap 5: de F4 wordt onderling gekruist.$$, 'inline'),
  ('4b86a572-3d49-46f3-96ae-6252feea4546', '3cfba86d-1f51-4412-9c82-9a0808c20163', $$uitwerkbijlage bij vraag 21: genoomaandeel Jinhua/Duroc per stap invullen$$,
   $$biologie-vwo-2019-i-aziatische-genen-verbeteren-het-europees-vleesvarken-context10.png$$,
   $$In de uitwerkbijlage staat een vereenvoudigde versie van het kruisingsschema (afbeelding 3), waarin de gebruikte individuen en groepen varkens zijn weergegeven als rondjes. Een zwart rondje betekent dat dit varken of deze groep varkens een 100% Jinhua-genoom heeft, een wit rondje betekent een 100% Duroc-genoom. In het schema is het genoom van de dieren bij stap 1 en stap 2 al ingevuld.$$, 'inline'),
  ('93c9936a-3b66-45c2-a91b-16f576396c91', '3cfba86d-1f51-4412-9c82-9a0808c20163', $$uitwerkbijlage: leeg kruisingsschema (stap 1 t/m 5) met Jinhua/Duroc-legenda$$,
   $$biologie-vwo-2019-i-aziatische-genen-verbeteren-het-europees-vleesvarken-context11.png$$,
   $$Uitwerkbijlage bij vraag 21: vereenvoudigd kruisingsschema met de stappen 1 tot en met 5 (Duroc-beer x Jinhua-zeugen, dan viermaal terugkruisen met een Duroc-beer, dan de F4 onderling kruisen tot F5). Bij stap 1 en stap 2 is het genoom van de dieren al ingevuld met een volledig zwart rondje (Jinhua-zeugen, 100% Jinhua) en een half zwart/half wit rondje (F1-zeugen); de overige rondjes (F2-zeugen, F3-zeugen, de Duroc-beren van stap 2 t/m 4, F4-beren, F4-zeugen en F5) zijn nog open (stippellijn) en moeten door de leerling worden ingekleurd volgens de legenda (open cirkel = Duroc, gevuld = Jinhua).$$, 'uitwerkbijlage'),
  ('015698ef-6dcf-4005-b994-d23cd06eb8c0', '3cfba86d-1f51-4412-9c82-9a0808c20163', $$DNA-markers maken efficiëntere inkruising van malsheidgenen mogelijk$$,
   $$biologie-vwo-2019-i-aziatische-genen-verbeteren-het-europees-vleesvarken-context12.png$$,
   $$Tegenwoordig kunnen eigenschappen van een ander ras dankzij DNA-technieken efficiënter ingekruist worden dan voorheen. Een recent voorbeeld komt uit Japan. De malsheid van varkensvlees wordt bepaald door een complex van genen op chromosoom 2 van het varkensgenoom. De Japanse onderzoekers voerden een serie kruisingen uit waarbij ze de zeugen selecteerden op basis van een DNA-test. Met behulp van genetische markers (bepaalde stukjes DNA of genen) selecteerden ze zeugen die de gewenste ‘malsheidgenen’ van het Jinhua-ras hadden, maar waarin het Duroc-genoom maximaal behouden was.$$, 'inline'),
  ('8dab38a5-f07b-483d-8c93-2c3255316f34', '3cfba86d-1f51-4412-9c82-9a0808c20163', $$veredelen op basis van fenotype is lastig als het genotype voor malsheid onbekend is$$,
   $$biologie-vwo-2019-i-aziatische-genen-verbeteren-het-europees-vleesvarken-context13.png$$,
   $$Bij de beschreven Japanse veredelingsmethode om malsheid te verbeteren in een hoogproductief varkensras, werd voor de selectie gebruikgemaakt van een DNA-techniek met markers. Dit werd gedaan omdat het heel lastig is om op malsheid te veredelen als het genotype voor malsheid van de varkens niet bekend is.$$, 'inline'),
  ('9c71680d-3a3f-46fa-bd35-9d98e852abbe', '3cfba86d-1f51-4412-9c82-9a0808c20163', $$drie typen genetische markers rond de doelwitlocus op chromosoom 2 (afbeelding 4)$$,
   $$biologie-vwo-2019-i-aziatische-genen-verbeteren-het-europees-vleesvarken-context14.png$$,
   $$Om alléén de malsheidgenen uit het Jinhua-genoom in het Duroc-genoom in te kruisen en voor de rest het Duroc-genoom zo veel mogelijk te behouden, zijn voor stap 3, 4 en 5 van het kruisings-programma (afbeelding 3) individuen geselecteerd op basis van genetische markers in het DNA. In afbeelding 4 zijn schematisch vier chromosomen van het varkens-genoom weergegeven. Met een wit blokje is de doelwitlocus op chromosoom 2 aangegeven: hier ligt het complex van genen dat de malsheid van het vlees bepaalt. Met pijltjes is de plaats van de verschillende markers aangegeven.
afbeelding 4: schema van vier chromosomen met daarop de doelwitlocus (wit blokje op chromosoom 2) en de posities van drie markertypen: type I (één marker dicht bij de doelwitlocus op chromosoom 2), type II (dezelfde marker als type I, plus extra markers op de overige chromosomen) en type III (extra markers dicht bij de doelwitlocus én op alle vier de chromosomen).$$, 'inline'),
  ('c056b1c0-a64d-4ab2-a249-fea0b39d5909', '3cfba86d-1f51-4412-9c82-9a0808c20163', $$drie typen markers hebben elk een eigen selectiedoel$$,
   $$biologie-vwo-2019-i-aziatische-genen-verbeteren-het-europees-vleesvarken-context15.png$$,
   $$De drie typen markers (I, II, III), hebben elk een eigen selectiedoel. Dieren werden alleen gebruikt om mee verder te fokken als alle drie de typen markers aangetoond konden worden.$$, 'inline'),
  ('0a11ee3a-4f54-4725-9c7d-c56438dcbf4e', '3cfba86d-1f51-4412-9c82-9a0808c20163', $$malsheidgenen zouden ook via recombinant-DNA-techniek ingebracht kunnen worden$$,
   $$biologie-vwo-2019-i-aziatische-genen-verbeteren-het-europees-vleesvarken-context16.png$$,
   $$De Japanse onderzoekers hadden de malsheidgenen uit het Jinhua-DNA ook met behulp van recombinant-DNA-techniek in het genoom van een Duroc-varken kunnen brengen.$$, 'inline'),
  ('9b861f90-1cde-4a00-9f6a-65ed032d911a', '8ccd3ea4-8d6d-4fd6-8759-25a0232f323d', $$inleiding: Clostridium difficile kan bij ziekenhuispatiënten gevaarlijke diarree veroorzaken$$,
   $$biologie-vwo-2019-i-diarreebacterie-slaat-toe-door-antibioticagebruik-context1.png$$,
   $$Veel gezonde mensen dragen de darmbacterie Clostridium difficile bij zich zonder er last van te hebben. Bij ziekenhuispatiënten kan deze bacterie echter een levensgevaarlijke diarree veroorzaken die lastig te genezen is. Ziekenhuizen treffen maatregelen om besmetting op te sporen en te voorkomen.$$, 'inline'),
  ('f50cc0b8-2388-4ead-80cd-b014117ab5bf', '8ccd3ea4-8d6d-4fd6-8759-25a0232f323d', $$C. difficile vormt sporen en toxines; CDAD ontstaat vooral bij breedspectrum-antibioticagebruik (afbeelding 1)$$,
   $$biologie-vwo-2019-i-diarreebacterie-slaat-toe-door-antibioticagebruik-context2.png$$,
   $$Clostridium difficile is een anaerobe bacteriesoort die ongunstige omstandigheden kan overleven in de vorm van sporen (afbeelding 1). Sommige C. difficile-stammen produceren toxische eiwitten. Door deze toxines gaan epitheelcellen van het dikkedarmslijmvlies dood, wat leidt tot een hardnekkige diarree die CDAD (Clostridium difficile associated diarrhea) wordt genoemd. De bacterie slaat vooral toe bij mensen die breedspectrum-antibiotica gebruiken. Deze antibiotica zijn werkzaam tegen verschillende bacteriën en worden veel toegepast in ziekenhuizen.
afbeelding 1: elektronenmicroscopische foto van C. difficile met sporen.$$, 'inline'),
  ('f1105de7-6c2d-4375-88a6-53c017d1c1cd', '8ccd3ea4-8d6d-4fd6-8759-25a0232f323d', $$het spijsverteringsstelsel biedt een natuurlijke bescherming tegen ziekteverwekkers$$,
   $$biologie-vwo-2019-i-diarreebacterie-slaat-toe-door-antibioticagebruik-context3.png$$,
   $$De bouw en werking van onderdelen van het spijsverteringsstelsel vormen bij een gezond mens een natuurlijke bescherming tegen ziekteverwekkende bacteriën zoals C. difficile.$$, 'inline'),
  ('92507011-a945-4de1-95f6-f23c3687566e', '8ccd3ea4-8d6d-4fd6-8759-25a0232f323d', $$darmflora bestaat uit honderden soorten symbiotische bacteriën$$,
   $$biologie-vwo-2019-i-diarreebacterie-slaat-toe-door-antibioticagebruik-context4.png$$,
   $$In de dikke darm leven honderden verschillende soorten symbiotische bacteriën, de zogenoemde darmflora. Commensalisme, mutualisme en parasitisme zijn verschillende vormen van symbiose.$$, 'inline'),
  ('37dafabf-6e75-458c-b6b7-58f153517e54', '8ccd3ea4-8d6d-4fd6-8759-25a0232f323d', $$C. difficile komt bij veel mensen symptoomloos voor in de darmflora$$,
   $$biologie-vwo-2019-i-diarreebacterie-slaat-toe-door-antibioticagebruik-context5.png$$,
   $$De darmbacteriën die deel uitmaken van een gezonde darmflora dragen bij aan de bescherming tegen ziekteverwekkende bacteriën. C. difficile is bij veel mensen aanwezig in de darmflora, zonder ziekteverschijnselen te veroorzaken.$$, 'inline'),
  ('de0dc2d4-e1f1-4cd2-87f7-f5a989c424dc', '8ccd3ea4-8d6d-4fd6-8759-25a0232f323d', $$C. difficile-toxinen beschadigen het buitenmembraan van mitochondriën en veroorzaken apoptose$$,
   $$biologie-vwo-2019-i-diarreebacterie-slaat-toe-door-antibioticagebruik-context6.png$$,
   $$De toxinen van C. difficile beschadigen in darmepitheelcellen het buitenmembraan van de mitochondriën. Dit leidt tot apoptose van deze darmcellen en dus tot verlies van darmepitheel.$$, 'inline'),
  ('cca7764a-8303-48fc-8ddd-423113662353', '8ccd3ea4-8d6d-4fd6-8759-25a0232f323d', $$DNA-strip test: preparatie van het fecesmonster en hybridisatie (afbeelding 2, 3)$$,
   $$biologie-vwo-2019-i-diarreebacterie-slaat-toe-door-antibioticagebruik-context7.png$$,
   $$Bij het vermoeden van een C. difficile-infectie wordt de ontlasting (feces) van de patiënt onderzocht op aanwezigheid van de bacterie en/of de toxinen. Daarnaast is er een DNA-strip ontwikkeld waarmee specifieke genen van C. difficile in het fecesmonster opgespoord kunnen worden. Het gaat om de genen die coderen voor toxine A, toxine B en voor binair toxine, en verder om bepaalde regulatorgenen (die de hoeveelheid toxine reguleren) en het resistentie-gen tegen het antibioticum moxifloxacine. Voorafgaand aan deze test wordt het fecesmonster geprepareerd, zoals schematisch is weergegeven in afbeelding 2. Daarbij worden DNA-strengen geproduceerd waaraan een biotinemolecuul (aan de 5’-kant van de primer) is gebonden. Hierna vindt de eigenlijke test plaats met een DNA-strip, zoals weergegeven in afbeelding 3.
afbeelding 2: schema van de monstervoorbereiding in vier stappen: DNA-isolatie uit fecesmonster, los DNA, vermenigvuldiging van DNA (met biotine-label), denatureren tot enkelstrengs DNA.
afbeelding 3: schema van de DNA-strip-test in drie stappen: hybridisatie van het DNA met specifieke probes op de strip, binding van een kleurstof, kleurontwikkeling tot een DNA-strip met gekleurde bandjes.$$, 'inline'),
  ('93036762-4019-4828-b4ba-13e818d3eb79', '8ccd3ea4-8d6d-4fd6-8759-25a0232f323d', $$legenda van de bandjes op de DNA-strip (afbeelding 4)$$,
   $$biologie-vwo-2019-i-diarreebacterie-slaat-toe-door-antibioticagebruik-context8.png$$,
   $$Het resultaat van zo’n test met een DNA-strip is in afbeelding 4 als voorbeeld weergegeven, met daarbij aangegeven de plaats en betekenis van de verschillende bandjes.
afbeelding 4: voorbeeld van een DNA-strip met bandjes voor kleuring controle, DNA-vermeerdering controle, C. difficile (tpi-locus en soortprobe), toxinegenen A en B, binair toxinegen, deletie in regulatorgen tcdC (vijf bandjes) en moxifloxacineresistentie (gyrA-probes).$$, 'inline'),
  ('cee26677-7b12-4f89-8959-a0cc6ee51c7a', '8ccd3ea4-8d6d-4fd6-8759-25a0232f323d', $$voorbeeld: zes gekleurde bandjes wijzen op een ongevaarlijke, moxifloxacinegevoelige stam$$,
   $$biologie-vwo-2019-i-diarreebacterie-slaat-toe-door-antibioticagebruik-context9.png$$,
   $$In dit voorbeeld zijn zes bandjes donker gekleurd. Daaruit blijkt dat in het fecesmonster van de patiënt een ongevaarlijke stam van C. difficile zit, die gevoelig is voor het antibioticum moxifloxacine.
Van vier patiënten met diarree wordt de ontlasting onderzocht met de DNA-striptest. De testuitslagen (bandjespatronen 1, 2, 3 en 4) van deze patiënten zijn in afbeelding 5 weergegeven.$$, 'inline'),
  ('3f4a46d4-9f46-447d-b446-684e45b18d8d', '8ccd3ea4-8d6d-4fd6-8759-25a0232f323d', $$testuitslagen (bandjespatronen) van vier patiënten (afbeelding 5)$$,
   $$biologie-vwo-2019-i-diarreebacterie-slaat-toe-door-antibioticagebruik-context10.png$$,
   $$afbeelding 5: DNA-strip-testresultaten van vier patiënten (1, 2, 3 en 4), met dezelfde bandjes-legenda als afbeelding 4 (kleuring controle, DNA-vermeerdering controle, C. difficile, toxinegenen, binair toxinegen, deletie in tcdC, moxifloxacineresistentie).$$, 'inline'),
  ('761772c9-b8c5-4deb-bb12-217cf3975cfa', '8ccd3ea4-8d6d-4fd6-8759-25a0232f323d', $$vier mogelijke diagnoses (P, Q, R, S)$$,
   $$biologie-vwo-2019-i-diarreebacterie-slaat-toe-door-antibioticagebruik-context11.png$$,
   $$De testuitslagen leiden tot vier diagnoses van de bijbehorende patiënten, die hieronder in willekeurige volgorde zijn weergegeven.
P: Bij deze patiënt wordt de diarree niet veroorzaakt door C. difficile.
Q: Deze patiënt is besmet met een pathogene stam van C. difficile, die bestreden kan worden met moxifloxacine.
R: Deze patiënt is besmet met een pathogene, moxifloxacine-resistente stam van C. difficile.
S: Van deze patiënt is de test onbetrouwbaar.$$, 'inline'),
  ('db6b4d0c-05fe-4ecb-a4d0-9965be46394f', '8ccd3ea4-8d6d-4fd6-8759-25a0232f323d', $$speurhond Cliff spoort C. difficile-besmetting op (afbeelding 6)$$,
   $$biologie-vwo-2019-i-diarreebacterie-slaat-toe-door-antibioticagebruik-context12.png$$,
   $$Het VU Medisch Centrum in Amsterdam treft extra maatregelen om een uitbraak van C. difficile te voorkomen. Daar ‘werkt’ de beagle Cliff (afbeelding 6), een speurhond die ruikt of een patiënt besmet is met C. difficile. Cliff is getraind om naast (het bed van) een besmette patiënt te gaan zitten.
afbeelding 6: foto van speurhond Cliff, een beagle met een hesje aan, in een ziekenhuisgang.$$, 'inline'),
  ('8f7cb2e8-0769-43f1-b02c-59165cd4cf1f', '8ccd3ea4-8d6d-4fd6-8759-25a0232f323d', $$fecestransplantatie bij hardnekkige CDAD; acht fecesmonsters van patiënt en donor$$,
   $$biologie-vwo-2019-i-diarreebacterie-slaat-toe-door-antibioticagebruik-context13.png$$,
   $$Bij patiënten met hardnekkige CDAD is fecestransplantatie bijzonder effectief gebleken. Hierbij wordt na een darmspoeling een fecessuspensie van een gezonde donor via een katheter rechtstreeks in de dunne darm gebracht. In een vakblad wordt de succesvolle fecestransplantatie beschreven van een vrouw die al acht maanden leed aan zeer ernstige CDAD. Ze kreeg een eenmalige transplantatie met feces van haar echtgenoot. Aan de hand van genetische vingerafdrukken van haar darmflora en die van het transplantaat kon het resultaat gevolgd worden. Daartoe zijn op verschillende momenten vóór en na de transplantatie in totaal acht fecesmonsters verzameld van haarzelf (de patiënt) en haar man (de donor). Elk monster, genummerd 1 tot en met 8, werd twee keer geanalyseerd (a en b).$$, 'inline'),
  ('d3b1f577-6083-4719-b129-b4907247b5a3', '8ccd3ea4-8d6d-4fd6-8759-25a0232f323d', $$dendrogram van de genetische overeenkomst tussen de fecesmonsters (afbeelding 7)$$,
   $$biologie-vwo-2019-i-diarreebacterie-slaat-toe-door-antibioticagebruik-context14.png$$,
   $$De resultaten zijn weergegeven in het dendrogram van afbeelding 7. Het dendrogram toont de mate van genetische overeenkomst tussen de monsters.
afbeelding 7: dendrogram (schaal van genetische overeenkomst 0 tot 0,96) van acht dubbel geanalyseerde fecesmonsters (1a/1b tot en met 8a/8b), gegroepeerd naar patiënt dag -7 (monsters 1, 2, 3), patiënt dag 0 (monster 5), donor dag 0 (monster 4), patiënt dag 14 (monsters 6, 7) en patiënt dag 33 (monster 8).$$, 'inline'),
  ('e89fe2fc-46de-4903-aec3-1b35065d53cb', '8ccd3ea4-8d6d-4fd6-8759-25a0232f323d', $$de behandeling was succesvol: na twee dagen had de vrouw weer vaste ontlasting$$,
   $$biologie-vwo-2019-i-diarreebacterie-slaat-toe-door-antibioticagebruik-context15.png$$,
   $$De behandeling was succesvol, want twee dagen na de transplantatie had de vrouw weer vaste ontlasting. In het dendrogram is het effect van de behandeling op de darmflora terug te zien.$$, 'inline'),
  ('b7045161-e777-4552-abaa-abe67b2ae516', 'bc27ae2d-7e42-40e0-a099-82c6fdba2563', $$inleiding: regelsystemen houden groeifactoren in de kas optimaal$$,
   $$biologie-vwo-2019-i-kas-vol-koolstofdioxide-context1.png$$,
   $$Moderne tomatenteeltbedrijven maken gebruik van complexe regelsystemen die alle factoren voor de plantengroei optimaal houden. Wat optimaal is, wordt bepaald door wetenschappelijk onderzoek en de praktijkervaring van telers.$$, 'inline'),
  ('68cf4e7d-f218-4d9f-86b1-60e48d4524c1', 'bc27ae2d-7e42-40e0-a099-82c6fdba2563', $$telers reguleren temperatuur en CO2-concentratie in de kas$$,
   $$biologie-vwo-2019-i-kas-vol-koolstofdioxide-context2.png$$,
   $$Een teler probeert in zijn kassen de productie van tomaten zo hoog mogelijk te maken door onder meer de temperatuur en de CO₂-concentratie te reguleren. In een gesloten kas kan de CO₂-concentratie dalen en daarmee de productie. Door in de zomer te ventileren wordt het niet te warm en blijft het CO₂-gehalte op peil. In de winter wordt aardgas verstookt voor verwarming en het daarbij gevormde CO₂ naar de kas geleid.$$, 'inline'),
  ('87cee405-c7b6-4f4d-bb82-4f532cce9acf', 'bc27ae2d-7e42-40e0-a099-82c6fdba2563', $$invloed van de CO2-concentratie op de tomatenproductie (afbeelding 1)$$,
   $$biologie-vwo-2019-i-kas-vol-koolstofdioxide-context3.png$$,
   $$De invloed van de CO₂-concentratie op de productie van tomatenplanten in experimenteerkassen is weergegeven in afbeelding 1. De productie bij de CO₂-concentratie van de buitenlucht is op 100% gesteld.
afbeelding 1: grafiek van de relatieve tomatenproductie (%) tegen de CO₂-concentratie in de kas; boven ongeveer 1000 ppm CO₂ neemt de productie nauwelijks verder toe.
In de experimenteerkassen blijkt een verhoging van de CO₂-dosering boven de 1000 ppm nauwelijks te leiden tot een verdere verhoging van de opbrengst aan tomaten.$$, 'inline'),
  ('273c419b-b7a3-4157-960a-7e464986717b', 'bc27ae2d-7e42-40e0-a099-82c6fdba2563', $$productie in de tomatenteelt versus netto primaire productie (NPP) in de ecologie$$,
   $$biologie-vwo-2019-i-kas-vol-koolstofdioxide-context4.png$$,
   $$In de tomatenteelt betekent ‘productie’ het aantal kilogram tomaten per oppervlakte in een bepaalde tijd. Dat is heel wat anders dan de in de ecologie gebruikte term netto primaire productie (NPP).$$, 'inline'),
  ('12cccda5-e990-49ff-ade9-5dc290206703', 'bc27ae2d-7e42-40e0-a099-82c6fdba2563', $$gangbare teelt op steenwol versus biologische teelt in aarde met compost$$,
   $$biologie-vwo-2019-i-kas-vol-koolstofdioxide-context5.png$$,
   $$Twee sectoren in de tomatenteelt zijn:
1 de gangbare teelt, waarbij de planten op steenwol groeien in een oplossing met voedingszouten
2 de biologische teelt, waarbij de planten groeien in aarde die regelmatig met compost wordt bijgemest
Om een even hoog CO₂-gehalte in de kas te handhaven hoeft bij de biologische teelt minder CO₂ toegevoegd te worden dan bij de gangbare teelt.$$, 'inline'),
  ('2edf9590-7523-4d43-b7d6-7cd4c25e3918', 'bc27ae2d-7e42-40e0-a099-82c6fdba2563', $$schermen temperen zonnestraling en beperken warmteverlies$$,
   $$biologie-vwo-2019-i-kas-vol-koolstofdioxide-context6.png$$,
   $$Uitrolbare schermen kunnen warmteverlies in de kas verminderen als het buiten koud is. Deze schermen worden ook gebruikt om op zomerse dagen de felle zonnestraling te temperen.$$, 'inline'),
  ('1f863434-06e7-4d88-9c68-f3e389136f3c', 'bc27ae2d-7e42-40e0-a099-82c6fdba2563', $$te veel zonnestraling beperkt de CO2-opname van de planten$$,
   $$biologie-vwo-2019-i-kas-vol-koolstofdioxide-context7.png$$,
   $$Bij te veel zonnestraling op zomerse dagen is er kans op opbrengstverlies als gevolg van een beperkte CO₂-opname van de planten.$$, 'inline'),
  ('d0104242-872f-4b92-91d2-cc7f59c0000a', 'bc27ae2d-7e42-40e0-a099-82c6fdba2563', $$halvering van de CO2-dosering leidde tot meer huidmondjes per cm2 bladoppervlak$$,
   $$biologie-vwo-2019-i-kas-vol-koolstofdioxide-context8.png$$,
   $$Gewoonlijk doseren tomatentelers de CO₂-concentratie in de kas tussen 800 en 1000 ppm. Onderzoekers van Wageningen University & Research hebben in twee experimenteerkassen de CO₂-dosering in de loop van de teeltperiode gehalveerd en het effect op de productie van tomaten onderzocht. Tegen de verwachting in bleek de productie vrijwel gelijk te blijven. Bij nader onderzoek bleek dat bij de gehalveerde CO₂-dosering het aantal huidmondjes per cm² bladoppervlak in de loop van het groeiseizoen groter was geworden.$$, 'inline');

