  ('428a0b85-90c0-4e24-b4c4-44678b3d8fe9', '3cfba86d-1f51-4412-9c82-9a0808c20163', 17,
   '[{"domain": "Populatie- en ecosysteemniveau", "subdomain": "Soortvorming"}]'::jsonb,
   '["isolatie", "natuurlijke selectie", "kunstmatige selectie", "genetische drift"]'::jsonb,
   $$Verklaren hoe geografische isolatie tot uiterlijke verschillen tussen twee varkensrassen kan leiden.$$,
   $$biologie-vwo-2019-i-aziatische-genen-verbeteren-het-europees-vleesvarken-vraag17.png$$, $$2p 17 Beschrijf twee manieren waarop de grote uiterlijke verschillen tussen deze twee varkensrassen kunnen zijn ontstaan.$$, array['a9ea2051-573d-48c0-ac96-3f87cdbb1f74']::uuid[]),
