   '[{"domain": "Populatie- en ecosysteemniveau", "subdomain": "Soortvorming"}]'::jsonb,
   '["genetische variatie", "fokkerij", "selectiemogelijkheden"]'::jsonb,
   $$Illustreren met een voorbeeld waarom genetische variatie voordelig is voor de vleesvarkenproductie.$$,
   $$biologie-vwo-2019-i-aziatische-genen-verbeteren-het-europees-vleesvarken-vraag18.png$$, $$1p 18 Beschrijf aan de hand van een voorbeeld dat genetische variatie voordelig kan zijn voor de vleesvarkenproductie.$$, array['8b9048f6-e010-4419-aaf7-0cd62f64eeba']::uuid[]),
